/* ---------------------------------------------------------
   Scroll-reveal hook
--------------------------------------------------------- */
function useReveal() {
  const ref = useRef(null);
  const [shown, setShown] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const obs = new IntersectionObserver(
      ([entry]) => { if (entry.isIntersecting) { setShown(true); obs.unobserve(el); } },
      { threshold: 0.15 }
    );
    obs.observe(el);
    return () => obs.disconnect();
  }, []);
  return [ref, shown];
}

function Reveal({ children, delay = 0, className = "" }) {
  const [ref, shown] = useReveal();
  return (
    <div
      ref={ref}
      className={className}
      style={{
        opacity: shown ? 1 : 0,
        transform: shown ? "translateY(0)" : "translateY(24px)",
        transition: `opacity 0.7s ease ${delay}ms, transform 0.7s ease ${delay}ms`,
      }}
    >
      {children}
    </div>
  );
}

/* ---------------------------------------------------------
   Terraced hillside divider — signature element
--------------------------------------------------------- */
function TerraceDivider({ flip = false, tone = "#F2F8ED" }) {
  return (
    <div style={{ transform: flip ? "scaleY(-1)" : "none", lineHeight: 0 }}>
      <svg viewBox="0 0 1200 90" width="100%" height="70" preserveAspectRatio="none">
        <path d="M0,90 L0,55 Q150,30 300,50 T600,45 T900,55 T1200,40 L1200,90 Z" fill="#DCEBD0" />
        <path d="M0,90 L0,68 Q150,48 300,64 T600,60 T900,68 T1200,58 L1200,90 Z" fill="#C3DFAE" />
        <path d={`M0,90 L0,80 Q150,68 300,78 T600,76 T900,80 T1200,74 L1200,90 Z`} fill={tone} />
      </svg>
    </div>
  );
}

